<?php
declare(strict_types=1);

require_once __DIR__ . '/../../includes/bootstrap.php';
$user = require_role(['staff', 'admin']);
$filters = ['action' => (string) ($_GET['action'] ?? ''), 'entity_type' => (string) ($_GET['entity_type'] ?? ''), 'from_date' => (string) ($_GET['from_date'] ?? ''), 'to_date' => (string) ($_GET['to_date'] ?? '')];
$error = null;
try { $entries = ActivityLog::findRecent($filters, $user); } catch (DomainException $exception) { $entries = []; $error = $exception->getMessage(); }
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Activity history | <?= e(APP_NAME) ?></title><link rel="stylesheet" href="../assets/app.css"></head>
<body><header class="site-header"><a href="../dashboard.php"><?= e(APP_NAME) ?></a><a href="../dashboard.php">Dashboard</a></header><main class="form-card"><h1>Activity history</h1><p>Showing up to 100 most recent entries. History cannot be edited or deleted.</p><?php if ($error): ?><p class="message error"><?= e($error) ?></p><?php endif; ?>
<form method="get" class="filter-form"><label for="action">Action</label><select id="action" name="action"><option value="">All actions</option><?php foreach (ActivityLog::actions() as $action): ?><option value="<?= e($action) ?>" <?= $filters['action'] === $action ? 'selected' : '' ?>><?= e($action) ?></option><?php endforeach; ?></select><label for="entity_type">Record type</label><select id="entity_type" name="entity_type"><option value="">All record types</option><?php foreach (['user', 'lost_report', 'found_report', 'found_item', 'claim'] as $type): ?><option value="<?= e($type) ?>" <?= $filters['entity_type'] === $type ? 'selected' : '' ?>><?= e($type) ?></option><?php endforeach; ?></select><label for="from_date">From date</label><input id="from_date" name="from_date" type="date" value="<?= e($filters['from_date']) ?>"><label for="to_date">To date</label><input id="to_date" name="to_date" type="date" value="<?= e($filters['to_date']) ?>"><button type="submit">Filter history</button></form>
<?php if ($entries === []): ?><p>No activity matches these filters.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Record</th><th>Details</th><th>IP</th></tr></thead><tbody><?php foreach ($entries as $entry): ?><tr><td><?= e((string) $entry['created_at']) ?></td><td><?= e((string) ($entry['actor_name'] ?? 'Unknown')) ?></td><td><?= e((string) $entry['action']) ?></td><td><?= e((string) ($entry['entity_type'] ?? '')) ?><?= $entry['entity_id'] ? ' #' . (int) $entry['entity_id'] : '' ?></td><td><?= e((string) ($entry['details'] ?? '')) ?></td><td><?= e((string) ($entry['ip_address'] ?? '')) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></main></body></html>
